def solution(storage, requests):
    from collections import deque

    n = len(storage)
    m = len(storage[0])
    grid = [[storage[i][j] for j in range(m)] for i in range(n)]

    def bfs(start_row, start_col, target):
        queue = deque([(start_row, start_col)])
        visited = set()
        visited.add((start_row, start_col))
        count = 0

        while queue:
            row, col = queue.popleft()
            if grid[row][col] == target:
                count += 1

            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                new_row, new_col = row + dr, col + dc
                if 0 <= new_row < n and 0 <= new_col < m and (new_row, new_col) not in visited:
                    visited.add((new_row, new_col))
                    queue.append((new_row, new_col))

        return count

    def remove_containers(target):
        nonlocal grid
        for i in range(n):
            for j in range(m):
                if grid[i][j] == target:
                    grid[i][j] = ''

    total_removed = 0

    for request in requests:
        if len(request) == 1:
            removed_count = bfs(0, 0, request)
            remove_containers(request)
            total_removed += removed_count
        else:
            removed_count = sum(bfs(i, j, request) for i in range(n) for j in range(m))
            remove_containers(request)
            total_removed += removed_count

    remaining_containers = sum(grid[i].count('') for i in range(n))
    return remaining_containers, total_removed

