def solution(edges):
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    def is_cycle(node, parent, visited):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor == parent:
                continue
            if neighbor in visited or not is_cycle(neighbor, node, visited):
                return False
        return True

    def count_graphs():
        nonlocal nodes_count
        visited = set()
        doughnut_count = 0
        stick_count = 0
        eight_cross_count = 0

        for node in range(nodes_count):
            if node not in visited:
                cycle_length = 0
                stack = [(node, -1)]
                while stack:
                    current, parent = stack.pop()
                    visited.add(current)
                    cycle_length += 1
                    for neighbor in graph[current]:
                        if neighbor != parent and neighbor not in visited:
                            stack.append((neighbor, current))
                if cycle_length > 1:
                    doughnut_count += 1
                elif cycle_length == 1:
                    stick_count += 1
                else:
                    eight_cross_count += 1

        return doughnut_count, stick_count, eight_cross_count

    nodes_count = max(graph.keys()) + 1
    doughnut_count, stick_count, eight_cross_count = count_graphs()

    return [doughnut_count, stick_count, eight_cross_count]
